## 1. Header Layout and Class Definitions

### 1.1 **Base Node and Variant Layout**

ART uses four node types for varying capacities. The base node includes crucial metadata, like the version counter.

```cpp
#include <atomic>
#include <array>
#include <span>
#include <memory>
#include <cstdint>
#include <immintrin.h>
#include <cassert>
#include <cstring>
#include <bit>

// Constants
constexpr size_t kMaxKeyBytesInline = 8;

struct NodeHeader {
    std::atomic<uint64_t> version_info; // [1 bit lock] [1 bit obsolete] [62-bit version]

    NodeHeader() : version_info(0) {}

    bool is_locked() const {
        return version_info.load(std::memory_order_acquire) & 0x8000000000000000ULL;
    }

    void lock() {
        uint64_t expected = version_info.load(std::memory_order_acquire);
        uint64_t locked = expected | 0x8000000000000000ULL;
        while (!version_info.compare_exchange_weak(expected, locked, 
                std::memory_order_acq_rel, std::memory_order_acquire)) {
            expected &= ~0x8000000000000000ULL; // Ensure expected is sane
        }
    }

    void unlock() {
        version_info.fetch_and(~0x8000000000000000ULL, std::memory_order_release);
    }
};

// Common base for all node types
struct BaseNode {
    NodeHeader header;
    uint8_t prefix[kMaxKeyBytesInline];
    uint32_t prefix_len;

    BaseNode() : prefix_len(0) {}

    virtual ~BaseNode() {}
    virtual size_t capacity() const = 0; // Define capacity-specific to each node type
};

struct Node4 : public BaseNode {
    std::array<uint8_t, 4> keys;
    std::array<std::atomic<BaseNode*>, 4> children;

    size_t capacity() const override { return 4; }
};

struct Node16 : public BaseNode {
    std::array<uint8_t, 16> keys;
    std::array<std::atomic<BaseNode*>, 16> children;

    size_t capacity() const override { return 16; }
};

struct Node48 : public BaseNode {
    std::array<uint8_t, 256> child_index; // Maps key to index (or 0xFF if absent)
    std::array<std::atomic<BaseNode*>, 48> children;

    Node48() { child_index.fill(0xFF); }
    size_t capacity() const override { return 48; }
};

struct Node256 : public BaseNode {
    std::array<std::atomic<BaseNode*>, 256> children;

    size_t capacity() const override { return 256; }
};
