#if defined(__x86_64__) || defined(_M_X64)
#include <emmintrin.h>
#include <smmintrin.h>
#endif

namespace mvart {

// Cache line alignment constant
constexpr size_t CACHE_LINE_SIZE = 64;
constexpr uint32_t MAX_PREFIX_LEN = 8;
constexpr uint64_t INF_TS = UINT64_MAX;

enum class NodeType : uint8_t {
    Node4   = 0,
    Node16  = 1,
    Node48  = 2,
    Node256 = 3,
    Leaf    = 4
};

//=============================================================================
// 1. Memory Reclamation Subsystem: 3-Epoch EBR
//=============================================================================

class EpochManager;

struct alignas(CACHE_LINE_SIZE) EpochSlot {
    std::atomic<uint64_t> epoch{0};
    std::atomic<bool> active{false};
    EpochSlot* next{nullptr};
};

struct RetiredNode {
    void* ptr;
    void (*deleter)(void*);
    RetiredNode* next;
};

class alignas(CACHE_LINE_SIZE) ThreadEpochContext {
public:
    EpochSlot* slot{nullptr};
    RetiredNode* retired_lists[3]{nullptr, nullptr, nullptr};
    size_t retired_count[3]{0, 0, 0};
    size_t ops_since_gc{0};

    ~ThreadEpochContext();
};

inline thread_local ThreadEpochContext t_epoch_ctx;

class EpochManager {
public:
    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    EpochSlot* register_thread() {
        EpochSlot* slot = new EpochSlot();
        slot->active.store(false, std::memory_order_relaxed);
        EpochSlot* head = m_head.load(std::memory_order_relaxed);
        do {
            slot->next = head;
        } while (!m_head.compare_exchange_weak(head, slot, 
                                                std::memory_order_release, 
                                                std::memory_order_relaxed));
        return slot;
    }

    void enter(ThreadEpochContext& ctx) {
        if (!ctx.slot) [[unlikely]] {
            ctx.slot = register_thread();
        }
        uint64_t global_ep = m_global_epoch.load(std::memory_order_relaxed);
        ctx.slot->epoch.store(global_ep, std::memory_order_relaxed);
        ctx.slot->active.store(true, std::memory_order_seq_cst);
    }

    void exit(ThreadEpochContext& ctx) {
        ctx.slot->active.store(false, std::memory_order_seq_cst);
        if (++ctx.ops_since_gc >= GC_CHECK_INTERVAL) {
            ctx.ops_since_gc = 0;
            try_advance_and_gc(ctx);
        }
    }

    template <typename T>
    void retire(ThreadEpochContext& ctx, T* ptr) {
        auto node = new RetiredNode{
            .ptr = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .next = nullptr
        };
        uint64_t ep = m_global_epoch.load(std::memory_order_relaxed) % 3;
        node->next = ctx.retired_lists[ep];
        ctx.retired_lists[ep] = node;
        ctx.retired_count[ep]++;
    }

    void try_advance_and_gc(ThreadEpochContext& ctx) {
        uint64_t cur_epoch = m_global_epoch.load(std::memory_order_relaxed);

        // Check if all threads have caught up to cur_epoch
        EpochSlot* curr = m_head.load(std::memory_order_acquire);
        while (curr) {
            if (curr->active.load(std::memory_order_acquire)) {
                if (curr->epoch.load(std::memory_order_acquire) < cur_epoch) {
                    return; // Cannot advance
                }
            }
            curr = curr->next;
        }

        // Advance global epoch
        if (m_global_epoch.compare_exchange_strong(cur_epoch, cur_epoch + 1,
                                                   std::memory_order_acq_rel,
                                                   std::memory_order_relaxed)) {
            // Free the retired records from (cur_epoch - 1) which is (cur_epoch + 2) % 3
            uint64_t free_epoch_idx = (cur_epoch + 2) % 3;
            reclaim_list(ctx.retired_lists[free_epoch_idx]);
            ctx.retired_lists[free_epoch_idx] = nullptr;
            ctx.retired_count[free_epoch_idx] = 0;
        }
    }

    uint64_t get_global_epoch() const {
        return m_global_epoch.load(std::memory_order_relaxed);
    }

private:
    EpochManager() : m_global_epoch(0), m_head(nullptr) {}
    ~EpochManager() = default;

    void reclaim_list(RetiredNode* head) {
        while (head) {
            RetiredNode* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
        }
    }

    static constexpr size_t GC_CHECK_INTERVAL = 64;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> m_global_epoch;
    alignas(CACHE_LINE_SIZE) std::atomic<EpochSlot*> m_head;
};

inline ThreadEpochContext::~ThreadEpochContext() {
    for (size_t i = 0; i < 3; ++i) {
        RetiredNode* head = retired_lists[i];
        while (head) {
            RetiredNode* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
        }
    }
}

class EpochGuard {
public:
    explicit EpochGuard(ThreadEpochContext& ctx = t_epoch_ctx) : m_ctx(ctx) {
        EpochManager::instance().enter(m_ctx);
    }
    ~EpochGuard() {
        EpochManager::instance().exit(m_ctx);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
private:
    ThreadEpochContext& m_ctx;
};

//=============================================================================
// 2. Lock-Free Version Records & Multi-Version Structures
//=============================================================================

struct VersionRecord {
    uint64_t commit_ts;
    uint64_t value;
    std::atomic<VersionRecord*> next;

    VersionRecord(uint64_t ts, uint64_t val, VersionRecord* nxt = nullptr)
        : commit_ts(ts), value(val), next(nxt) {}
};

//=============================================================================
// 3. Optimistic Node Header & ART Nodes
//=============================================================================

struct NodeHeader {
    // [1 bit: Lock] [1 bit: Obsolete] [62 bits: Version counter]
    std::atomic<uint64_t> version_lock{0};
    NodeType type;
    uint8_t prefix_len{0};
    uint8_t prefix[MAX_PREFIX_LEN]{0};

    static constexpr uint64_t LOCK_BIT     = 0b01;
    static constexpr uint64_t OBSOLETE_BIT = 0b10;
    static constexpr uint64_t VERSION_INCR = 0b100;

    explicit NodeHeader(NodeType t) : type(t) {}

    bool is_locked(uint64_t v) const { return (v & LOCK_BIT) != 0; }
    bool is_obsolete(uint64_t v) const { return (v & OBSOLETE_BIT) != 0; }

    uint64_t read_version_begin() const {
        uint64_t v = version_lock.load(std::memory_order_acquire);
        while (is_locked(v)) {
            _mm_pause();
            v = version_lock.load(std::memory_order_acquire);
        }
        return v;
    }

    bool validate(uint64_t old_version) const {
        std::atomic_thread_fence(std::memory_order_acquire);
        return version_lock.load(std::memory_order_relaxed) == old_version;
    }

    bool upgrade_to_write_lock(uint64_t& current_version) {
        if (version_lock.compare_exchange_strong(current_version, 
                                                 current_version | LOCK_BIT,
                                                 std::memory_order_acquire, 
                                                 std::memory_order_relaxed)) {
            current_version |= LOCK_BIT;
            return true;
        }
        return false;
    }

    void write_lock() {
        uint64_t v = version_lock.load(std::memory_order_relaxed);
        while (true) {
            if (!is_locked(v) && !is_obsolete(v)) {
                if (version_lock.compare_exchange_weak(v, v | LOCK_BIT,
                                                       std::memory_order_acquire,
                                                       std::memory_order_relaxed)) {
                    return;
                }
            }
            _mm_pause();
            v = version_lock.load(std::memory_order_relaxed);
        }
    }

    void write_unlock() {
        uint64_t v = version_lock.load(std::memory_order_relaxed);
        assert(is_locked(v));
        version_lock.store((v + VERSION_INCR) & ~LOCK_BIT, std::memory_order_release);
    }

    void write_unlock_obsolete() {
        uint64_t v = version_lock.load(std::memory_order_relaxed);
        assert(is_locked(v));
        version_lock.store(v | OBSOLETE_BIT, std::memory_order_release);
    }
};

struct LeafNode : public NodeHeader {
    std::atomic<VersionRecord*> version_head{nullptr};
    uint32_t key_len;
    uint8_t key_bytes[1]; // Flexible array payload

    static LeafNode* create(std::span<const uint8_t> key, uint64_t ts, uint64_t value) {
        size_t alloc_sz = sizeof(LeafNode) + key.size() - 1;
        void* mem = ::operator new(alloc_sz);
        auto* leaf = new (mem) LeafNode(key);
        auto* vrec = new VersionRecord(ts, value, nullptr);
        leaf->version_head.store(vrec, std::memory_order_release);
        return leaf;
    }

    explicit LeafNode(std::span<const uint8_t> key) 
        : NodeHeader(NodeType::Leaf), key_len(static_cast<uint32_t>(key.size())) {
        std::memcpy(key_bytes, key.data(), key.size());
    }

    std::span<const uint8_t> get_key() const {
        return {key_bytes, key_len};
    }
};

struct Node4 : public NodeHeader {
    uint8_t count{0};
    uint8_t keys[4]{0};
    std::atomic<NodeHeader*> children[4]{nullptr, nullptr, nullptr, nullptr};

    Node4() : NodeHeader(NodeType::Node4) {}

    int find_child(uint8_t byte) const {
        for (int i = 0; i < count; ++i) {
            if (keys[i] == byte) return i;
        }
        return -1;
    }

    void add_child(uint8_t byte, NodeHeader* child) {
        int idx = count;
        while (idx > 0 && keys[idx - 1] > byte) {
            keys[idx] = keys[idx - 1];
            children[idx].store(children[idx - 1].load(std::memory_order_relaxed), std::memory_order_relaxed);
            idx--;
        }
        keys[idx] = byte;
        children[idx].store(child, std::memory_order_relaxed);
        count++;
    }
};

struct Node16 : public NodeHeader {
    uint8_t count{0};
    uint8_t keys[16]{0};
    std::atomic<NodeHeader*> children[16]{nullptr};

    Node16() : NodeHeader(NodeType::Node16) {}

    int find_child(uint8_t byte) const {
#if defined(__x86_64__) || defined(_M_X64)
        __m128i key_vec = _mm_set1_epi8(static_cast<char>(byte));
        __m128i node_keys = _mm_loadu_si128(reinterpret_cast<const __m128i*>(keys));
        __m128i cmp = _mm_cmpeq_epi8(key_vec, node_keys);
        int mask = _mm_movemask_epi8(cmp) & ((1 << count) - 1);
        if (mask != 0) {
            return std::countr_zero(static_cast<unsigned int>(mask));
        }
        return -1;
#else
        for (int i = 0; i < count; ++i) {
            if (keys[i] == byte) return i;
        }
        return -1;
#endif
    }

    void add_child(uint8_t byte, NodeHeader* child) {
        int idx = 0;
        while (idx < count && keys[idx] < byte) idx++;
        std::memmove(&keys[idx + 1], &keys[idx], count - idx);
        for (int i = count; i > idx; --i) {
            children[i].store(children[i - 1].load(std::memory_order_relaxed), std::memory_order_relaxed);
        }
        keys[idx] = byte;
        children[idx].store(child, std::memory_order_relaxed);
        count++;
    }
};

struct Node48 : public NodeHeader {
    uint8_t count{0};
    uint8_t child_indices[256];
    std::atomic<NodeHeader*> children[48]{nullptr};

    static constexpr uint8_t EMPTY_MARKER = 48;

    Node48() : NodeHeader(NodeType::Node48) {
        std::memset(child_indices, EMPTY_MARKER, sizeof(child_indices));
    }

    int find_child(uint8_t byte) const {
        uint8_t idx = child_indices[byte];
        return (idx != EMPTY_MARKER) ? idx : -1;
    }

    void add_child(uint8_t byte, NodeHeader* child) {
        uint8_t idx = 0;
        while (children[idx].load(std::memory_order_relaxed) != nullptr) idx++;
        children[idx].store(child, std::memory_order_relaxed);
        child_indices[byte] = idx;
        count++;
    }
};

struct Node256 : public NodeHeader {
    uint16_t count{0};
    std::atomic<NodeHeader*> children[256]{nullptr};

    Node256() : NodeHeader(NodeType::Node256) {}

    int find_child(uint8_t byte) const {
        return byte;
    }

    void add_child(uint8_t byte, NodeHeader* child) {
        children[byte].store(child, std::memory_order_relaxed);
        count++;
    }
};

// Helper to extract a pointer to child safely under OLC
inline NodeHeader* get_child(const NodeHeader* node, uint8_t byte) {
    switch (node->type) {
        case NodeType::Node4: {
            auto* n = static_cast<const Node4*>(node);
            int idx = n->find_child(byte);
            return (idx >= 0) ? n->children[idx].load(std::memory_order_acquire) : nullptr;
        }
        case NodeType::Node16: {
            auto* n = static_cast<const Node16*>(node);
            int idx = n->find_child(byte);
            return (idx >= 0) ? n->children[idx].load(std::memory_order_acquire) : nullptr;
        }
        case NodeType::Node48: {
            auto* n = static_cast<const Node48*>(node);
            int idx = n->find_child(byte);
            return (idx >= 0) ? n->children[idx].load(std::memory_order_acquire) : nullptr;
        }
        case NodeType::Node256: {
            auto* n = static_cast<const Node256*>(node);
            return n->children[byte].load(std::memory_order_acquire);
        }
        default:
            return nullptr;
    }
}

//=============================================================================
// 4. Ring Buffer WAL & Group Commit
//=============================================================================

struct alignas(CACHE_LINE_SIZE) LogRecordHeader {
    uint32_t size;
    uint64_t commit_ts;
    uint32_t key_size;
    uint64_t value;
};

class ConcurrentWAL {
public:
    static constexpr size_t BUFFER_SIZE = 16 * 1024 * 1024; // 16MB Ring Buffer

    explicit ConcurrentWAL(const std::string& path = "/dev/null") 
        : m_buffer(new uint8_t[BUFFER_SIZE]), m_head(0), m_tail(0), m_flushed_tail(0), m_running(true) {
        m_flush_worker = std::jthread([this](std::stop_token st) { flush_loop(st); });
    }

    ~ConcurrentWAL() {
        m_running.store(false, std::memory_order_release);
        if (m_flush_worker.joinable()) {
            m_flush_worker.request_stop();
        }
        delete[] m_buffer;
    }

    uint64_t append_record(uint64_t commit_ts, std::span<const uint8_t> key, uint64_t val) {
        uint32_t total_sz = sizeof(LogRecordHeader) + static_cast<uint32_t>(key.size());
        uint64_t offset = m_tail.fetch_add(total_sz, std::memory_order_acq_rel);

        uint64_t ring_idx = offset % BUFFER_SIZE;
        LogRecordHeader hdr{
            .size = total_sz,
            .commit_ts = commit_ts,
            .key_size = static_cast<uint32_t>(key.size()),
            .value = val
        };

        if (ring_idx + total_sz <= BUFFER_SIZE) {
            std::memcpy(m_buffer + ring_idx, &hdr, sizeof(hdr));
            std::memcpy(m_buffer + ring_idx + sizeof(hdr), key.data(), key.size());
        } else {
            // Unaligned wrap-around payload write
            uint32_t first_chunk = BUFFER_SIZE - ring_idx;
            uint8_t temp[sizeof(LogRecordHeader)];
            std::memcpy(temp, &hdr, sizeof(hdr));

            for (size_t i = 0; i < sizeof(hdr); ++i) {
                m_buffer[(ring_idx + i) % BUFFER_SIZE] = temp[i];
            }
            for (size_t i = 0; i < key.size(); ++i) {
                m_buffer[(ring_idx + sizeof(hdr) + i) % BUFFER_SIZE] = key[i];
            }
        }

        m_head.fetch_add(total_sz, std::memory_order_release);
        return offset + total_sz;
    }

    void wait_flush(uint64_t ticket) {
        while (m_flushed_tail.load(std::memory_order_acquire) < ticket) {
            _mm_pause();
        }
    }

private:
    void flush_loop(std::stop_token st) {
        while (!st.stop_requested() && m_running.load(std::memory_order_relaxed)) {
            uint64_t produced = m_head.load(std::memory_order_acquire);
            uint64_t flushed = m_flushed_tail.load(std::memory_order_relaxed);

            if (produced > flushed) {
                // Simulate atomic batch disk I/O (e.g. io_uring / Direct I/O pwritev)
                m_flushed_tail.store(produced, std::memory_order_release);
            } else {
                std::this_thread::yield();
            }
        }
    }

    alignas(CACHE_LINE_SIZE) uint8_t* m_buffer;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> m_head;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> m_tail;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> m_flushed_tail;
    std::atomic<bool> m_running;
    std::jthread m_flush_worker;
};

//=============================================================================
// 5. MV-ART Complete Implementation
//=============================================================================

struct TxnContext {
    uint64_t read_ts{INF_TS};
    uint64_t commit_ts{0};
    ThreadEpochContext& epoch_ctx{t_epoch_ctx};
};

class MVARTIndex {
public:
    MVARTIndex() : m_root(nullptr), m_global_ts(1) {}

    ~MVARTIndex() {
        // Reclamation handled via EBR lifecycle
    }

    uint64_t allocate_ts() {
        return m_global_ts.fetch_add(1, std::memory_order_relaxed);
    }

    // ------------------------------------------------------------------------
    // Point Lookup (Lock-Free Read Fast-Path with OLC Validation)
    // ------------------------------------------------------------------------
    bool get(TxnContext& ctx, std::span<const uint8_t> key, uint64_t read_ts, uint64_t& out_value) {
        EpochGuard guard(ctx.epoch_ctx);

    restart:
        NodeHeader* curr = m_root.load(std::memory_order_acquire);
        if (!curr) return false;

        uint32_t depth = 0;

        while (curr) {
            uint64_t v = curr->read_version_begin();

            if (curr->type == NodeType::Leaf) {
                auto* leaf = static_cast<LeafNode*>(curr);
                if (!curr->validate(v)) goto restart;

                auto leaf_key = leaf->get_key();
                if (leaf_key.size() != key.size() || 
                    std::memcmp(leaf_key.data(), key.data(), key.size()) != 0) {
                    return false;
                }

                // Traverse lock-free MVCC version chain
                VersionRecord* vrec = leaf->version_head.load(std::memory_order_acquire);
                while (vrec) {
                    if (vrec->commit_ts <= read_ts) {
                        out_value = vrec->value;
                        return true;
                    }
                    vrec = vrec->next.load(std::memory_order_acquire);
                }
                return false;
            }

            // Path prefix check
            if (curr->prefix_len > 0) {
                uint32_t match_len = check_prefix(curr, key, depth);
                if (match_len < curr->prefix_len) {
                    if (!curr->validate(v)) goto restart;
                    return false;
                }
                depth += curr->prefix_len;
            }

            if (depth >= key.size()) {
                if (!curr->validate(v)) goto restart;
                return false;
            }

            uint8_t byte = key[depth];
            NodeHeader* next = get_child(curr, byte);

            if (!curr->validate(v)) goto restart;
            if (!next) return false;

            depth++;
            curr = next;
        }

        return false;
    }

    // ------------------------------------------------------------------------
    // Insert / Multi-Version Upsert with First-Committer-Wins CAS
    // ------------------------------------------------------------------------
    bool insert(TxnContext& ctx, std::span<const uint8_t> key, uint64_t value, ConcurrentWAL* wal = nullptr) {
        EpochGuard guard(ctx.epoch_ctx);

    restart:
        NodeHeader* root_node = m_root.load(std::memory_order_acquire);
        if (!root_node) {
            uint64_t ts = allocate_ts();
            LeafNode* new_leaf = LeafNode::create(key, ts, value);
            if (m_root.compare_exchange_strong(root_node, new_leaf,
                                               std::memory_order_release,
                                               std::memory_order_relaxed)) {
                if (wal) {
                    uint64_t ticket = wal->append_record(ts, key, value);
                    wal->wait_flush(ticket);
                }
                return true;
            }
            // Lost CAS race, clean up and restart
            delete new_leaf;
            goto restart;
        }

        NodeHeader* parent = nullptr;
        NodeHeader* curr = root_node;
        uint64_t parent_v = 0;
        uint32_t depth = 0;

        while (true) {
            uint64_t curr_v = curr->read_version_begin();

            if (curr->type == NodeType::Leaf) {
                auto* leaf = static_cast<LeafNode*>(curr);
                if (!curr->validate(curr_v)) goto restart;

                auto leaf_key = leaf->get_key();
                if (leaf_key.size() == key.size() && 
                    std::memcmp(leaf_key.data(), key.data(), key.size()) == 0) {
                    // Update key: First-Committer-Wins CAS on version chain
                    uint64_t ts = allocate_ts();
                    VersionRecord* old_head = leaf->version_head.load(std::memory_order_relaxed);
                    auto* new_rec = new VersionRecord(ts, value, old_head);

                    while (!leaf->version_head.compare_exchange_weak(old_head, new_rec,
                                                                    std::memory_order_acq_rel,
                                                                    std::memory_order_acquire)) {
                        new_rec->next.store(old_head, std::memory_order_relaxed);
                        _mm_pause();
                    }

                    if (wal) {
                        uint64_t ticket = wal->append_record(ts, key, value);
                        wal->wait_flush(ticket);
                    }
                    return true;
                }

                // Divergence at Leaf: Need node splitting
                if (parent) {
                    if (!parent->upgrade_to_write_lock(parent_v)) goto restart;
                }
                if (!curr->upgrade_to_write_lock(curr_v)) {
                    if (parent) parent->write_unlock();
                    goto restart;
                }

                // Construct new internal node and perform lazy expansion
                uint32_t match_len = 0;
                while (depth + match_len < key.size() && 
                       depth + match_len < leaf_key.size() && 
                       key[depth + match_len] == leaf_key[depth + match_len]) {
                    match_len++;
                }

                Node4* split_node = new Node4();
                split_node->prefix_len = std::min(match_len, MAX_PREFIX_LEN);
                for (uint32_t i = 0; i < split_node->prefix_len; ++i) {
                    split_node->prefix[i] = key[depth + i];
                }

                uint64_t ts = allocate_ts();
                LeafNode* new_leaf = LeafNode::create(key, ts, value);

                uint8_t byte_curr = (depth + match_len < leaf_key.size()) ? leaf_key[depth + match_len] : 0;
                uint8_t byte_new = (depth + match_len < key.size()) ? key[depth + match_len] : 0;

                split_node->add_child(byte_curr, leaf);
                split_node->add_child(byte_new, new_leaf);

                if (parent == nullptr) {
                    m_root.store(split_node, std::memory_order_release);
                } else {
                    replace_child(parent, key[depth - 1], split_node);
                    parent->write_unlock();
                }

                curr->write_unlock();
                if (wal) {
                    uint64_t ticket = wal->append_record(ts, key, value);
                    wal->wait_flush(ticket);
                }
                return true;
            }

            // Interior node prefix matching
            if (curr->prefix_len > 0) {
                uint32_t match_len = check_prefix(curr, key, depth);
                if (match_len < curr->prefix_len) {
                    // Split prefix
                    if (parent && !parent->upgrade_to_write_lock(parent_v)) goto restart;
                    if (!curr->upgrade_to_write_lock(curr_v)) {
                        if (parent) parent->write_unlock();
                        goto restart;
                    }

                    Node4* split_node = new Node4();
                    split_node->prefix_len = match_len;
                    for (uint32_t i = 0; i < match_len; ++i) {
                        split_node->prefix[i] = curr->prefix[i];
                    }

                    // Update existing node's prefix
                    curr->prefix_len -= (match_len + 1);
                    uint8_t old_byte = curr->prefix[match_len];
                    for (uint32_t i = 0; i < curr->prefix_len; ++i) {
                        curr->prefix[i] = curr->prefix[match_len + 1 + i];
                    }

                    uint64_t ts = allocate_ts();
                    LeafNode* new_leaf = LeafNode::create(key, ts, value);
                    uint8_t new_byte = key[depth + match_len];

                    split_node->add_child(old_byte, curr);
                    split_node->add_child(new_byte, new_leaf);

                    if (parent == nullptr) {
                        m_root.store(split_node, std::memory_order_release);
                    } else {
                        replace_child(parent, key[depth - 1], split_node);
                        parent->write_unlock();
                    }

                    curr->write_unlock();
                    if (wal) {
                        uint64_t ticket = wal->append_record(ts, key, value);
                        wal->wait_flush(ticket);
                    }
                    return true;
                }
                depth += curr->prefix_len;
            }

            uint8_t byte = key[depth];
            NodeHeader* next = get_child(curr, byte);

            if (!curr->validate(curr_v)) goto restart;

            if (!next) {
                if (!curr->upgrade_to_write_lock(curr_v)) goto restart;

                uint64_ts_val:
                uint64_t ts = allocate_ts();
                LeafNode* new_leaf = LeafNode::create(key, ts, value);

                if (is_full(curr)) {
                    NodeHeader* upgraded = upgrade_node(curr, byte, new_leaf);
                    if (parent == nullptr) {
                        m_root.store(upgraded, std::memory_order_release);
                    } else {
                        parent->write_lock();
                        replace_child(parent, key[depth - curr->prefix_len - 1], upgraded);
                        parent->write_unlock();
                    }
                    curr->write_unlock_obsolete();
                    EpochManager::instance().retire(ctx.epoch_ctx, curr);
                } else {
                    add_child_to_node(curr, byte, new_leaf);
                    curr->write_unlock();
                }

                if (wal) {
                    uint64_t ticket = wal->append_record(ts, key, value);
                    wal->wait_flush(ticket);
                }
                return true;
            }

            parent = curr;
            parent_v = curr_v;
            curr = next;
            depth++;
        }
    }

    // ------------------------------------------------------------------------
    // Range Scan Implementation under Snapshot Isolation
    // ------------------------------------------------------------------------
    void scan(TxnContext& ctx, 
              std::span<const uint8_t> start_key, 
              std::span<const uint8_t> end_key, 
              uint64_t read_ts, 
              const std::function<bool(std::span<const uint8_t>, uint64_t)>& callback) {
        EpochGuard guard(ctx.epoch_ctx);
        scan_cursor(m_root.load(std::memory_order_acquire), start_key, end_key, read_ts, 0, callback);
    }

private:
    uint32_t check_prefix(const NodeHeader* node, std::span<const uint8_t> key, uint32_t depth) {
        uint32_t max_cmp = std::min(static_cast<uint32_t>(node->prefix_len), 
                                    static_cast<uint32_t>(key.size() - depth));
        for (uint32_t i = 0; i < max_cmp; ++i) {
            if (node->prefix[i] != key[depth + i]) return i;
        }
        return max_cmp;
    }

    bool is_full(const NodeHeader* node) {
        switch (node->type) {
            case NodeType::Node4:   return static_cast<const Node4*>(node)->count == 4;
            case NodeType::Node16:  return static_cast<const Node16*>(node)->count == 16;
            case NodeType::Node48:  return static_cast<const Node48*>(node)->count == 48;
            case NodeType::Node256: return false;
            default: return false;
        }
    }

    void add_child_to_node(NodeHeader* node, uint8_t byte, NodeHeader* child) {
        switch (node->type) {
            case NodeType::Node4:   static_cast<Node4*>(node)->add_child(byte, child); break;
            case NodeType::Node16:  static_cast<Node16*>(node)->add_child(byte, child); break;
            case NodeType::Node48:  static_cast<Node48*>(node)->add_child(byte, child); break;
            case NodeType::Node256: static_cast<Node256*>(node)->add_child(byte, child); break;
            default: break;
        }
    }

    void replace_child(NodeHeader* parent, uint8_t byte, NodeHeader* new_child) {
        switch (parent->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(parent);
                int idx = n->find_child(byte);
                assert(idx >= 0);
                n->children[idx].store(new_child, std::memory_order_release);
                break;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(parent);
                int idx = n->find_child(byte);
                assert(idx >= 0);
                n->children[idx].store(new_child, std::memory_order_release);
                break;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(parent);
                int idx = n->find_child(byte);
                assert(idx >= 0);
                n->children[idx].store(new_child, std::memory_order_release);
                break;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(parent);
                n->children[byte].store(new_child, std::memory_order_release);
                break;
            }
            default: break;
        }
    }

    NodeHeader* upgrade_node(NodeHeader* old_node, uint8_t byte, NodeHeader* new_child) {
        switch (old_node->type) {
            case NodeType::Node4: {
                auto* n4 = static_cast<Node4*>(old_node);
                auto* n16 = new Node16();
                n16->count = n4->count;
                n16->prefix_len = n4->prefix_len;
                std::memcpy(n16->prefix, n4->prefix, n4->prefix_len);
                std::memcpy(n16->keys, n4->keys, 4);
                for (int i = 0; i < 4; ++i) {
                    n16->children[i].store(n4->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                }
                n16->add_child(byte, new_child);
                return n16;
            }
            case NodeType::Node16: {
                auto* n16 = static_cast<Node16*>(old_node);
                auto* n48 = new Node48();
                n48->count = n16->count;
                n48->prefix_len = n16->prefix_len;
                std::memcpy(n48->prefix, n16->prefix, n16->prefix_len);
                for (int i = 0; i < 16; ++i) {
                    n48->child_indices[n16->keys[i]] = i;
                    n48->children[i].store(n16->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                }
                n48->add_child(byte, new_child);
                return n48;
            }
            case NodeType::Node48: {
                auto* n48 = static_cast<Node48*>(old_node);
                auto* n256 = new Node256();
                n256->count = n48->count;
                n256->prefix_len = n48->prefix_len;
                std::memcpy(n256->prefix, n48->prefix, n48->prefix_len);
                for (int i = 0; i < 256; ++i) {
                    uint8_t idx = n48->child_indices[i];
                    if (idx != Node48::EMPTY_MARKER) {
                        n256->children[i].store(n48->children[idx].load(std::memory_order_relaxed), std::memory_order_relaxed);
                    }
                }
                n256->add_child(byte, new_child);
                return n256;
            }
            default:
                return nullptr;
        }
    }

    bool scan_cursor(NodeHeader* curr, 
                     std::span<const uint8_t> start, 
                     std::span<const uint8_t> end, 
                     uint64_t read_ts, 
                     uint32_t depth,
                     const std::function<bool(std::span<const uint8_t>, uint64_t)>& cb) {
        if (!curr) return true;

        if (curr->type == NodeType::Leaf) {
            auto* leaf = static_cast<LeafNode*>(curr);
            auto key = leaf->get_key();

            // Check range boundaries
            if (!start.empty() && key < start) return true;
            if (!end.empty() && key > end) return false;

            // Resolve snapshot version
            VersionRecord* vrec = leaf->version_head.load(std::memory_order_acquire);
            while (vrec) {
                if (vrec->commit_ts <= read_ts) {
                    return cb(key, vrec->value);
                }
                vrec = vrec->next.load(std::memory_order_acquire);
            }
            return true;
        }

        // Iterate sorted children
        switch (curr->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(curr);
                for (int i = 0; i < n->count; ++i) {
                    if (!scan_cursor(n->children[i].load(std::memory_order_acquire), start, end, read_ts, depth + 1, cb)) {
                        return false;
                    }
                }
                break;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(curr);
                for (int i = 0; i < n->count; ++i) {
                    if (!scan_cursor(n->children[i].load(std::memory_order_acquire), start, end, read_ts, depth + 1, cb)) {
                        return false;
                    }
                }
                break;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(curr);
                for (int i = 0; i < 256; ++i) {
                    uint8_t idx = n->child_indices[i];
                    if (idx != Node48::EMPTY_MARKER) {
                        if (!scan_cursor(n->children[idx].load(std::memory_order_acquire), start, end, read_ts, depth + 1, cb)) {
                            return false;
                        }
                    }
                }
                break;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(curr);
                for (int i = 0; i < 256; ++i) {
                    NodeHeader* child = n->children[i].load(std::memory_order_acquire);
                    if (child) {
                        if (!scan_cursor(child, start, end, read_ts, depth + 1, cb)) {
                            return false;
                        }
                    }
                }
                break;
            }
            default: break;
        }
        return true;
    }

    alignas(CACHE_LINE_SIZE) std::atomic<NodeHeader*> m_root;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> m_global_ts;
};

} // namespace mvart
