int main() {
    using namespace mvart;

    MVARTIndex index;
    ConcurrentWAL wal;

    TxnContext writer_ctx;
    TxnContext reader_ctx;

    // Concurrent MVCC Insertions
    uint8_t k1[] = {'u', 's', 'e', 'r', '_', '1'};
    uint8_t k2[] = {'u', 's', 'e', 'r', '_', '2'};

    index.insert(writer_ctx, k1, 1001, &wal);
    index.insert(writer_ctx, k1, 1002, &wal); // Updated MVCC version
    index.insert(writer_ctx, k2, 2001, &wal);

    // Read Snapshot at TS = 1 vs TS = 2
    uint64_t val = 0;
    if (index.get(reader_ctx, k1, 1, val)) {
        std::cout << "TS 1 Read Key1: " << val << "\n"; // Output: 1001
    }

    if (index.get(reader_ctx, k1, 2, val)) {
        std::cout << "TS 2 Read Key1: " << val << "\n"; // Output: 1002
    }

    // Range Scan
    std::cout << "Range scan across all keys:\n";
    index.scan(reader_ctx, {}, {}, 2, [](std::span<const uint8_t> k, uint64_t v) {
        std::string s(k.begin(), k.end());
        std::cout << "  " << s << " -> " << v << "\n";
        return true;
    });

    return 0;
}
